#!/bin/bash

# ==============================================================================
# Script: run_benchmark.sh
# Description: This script automates the end-to-end benchmarking process for C++
#              functions. It compiles a specified C++ source file, executes the
#              resulting benchmark program, and then uses a Python script to
#              plot the generated results.
# Author: Syed Taha
# Date: June 26, 2025
#
# Usage:
#   ./run_benchmark.sh [OPTION] <source_directory>
#
# Options:
#   -c                   Clean all generated files (build/, plots/, logs/).
#                        This option is useful for resetting the environment.
#   -h                   Display this help message and exit.
#
# Arguments:
#   <source_directory>   The path to the directory containing your main C++
#                        source file (main.cpp). This directory name is also
#                        used to determine the output CSV filename.
#
# Assumptions:
#   - A C++ compiler (g++) is installed and accessible in the system's PATH.
#   - Python 3 is installed and accessible via the 'python3' command.
#   - Your C++ program (${MAIN_CPP_SOURCE_FILE}) expects its necessary header
#     files (e.g., FUNCTION_BENCHMARK.HPP, utils.hpp) to be discoverable by 'g++'
#     via relative paths from your C++ source files (e.g., #include "../utils.hpp").
#     No explicit -I (include path) flags are added by this script.
#   - The C++ program will generate a CSV file named 'raw_<source_directory_name>_data.csv'
#     inside 'logs/' which it creates relative to the **current working directory**
#     where this `run_benchmark.sh` script is executed.
#   - The Python plotting script ('${PYTHON_PLOTTER_SCRIPT}') is located in the
#     same directory as this shell script.
# ==============================================================================

# ================= Configuration Variables =================
# Directory where compiled executables will be placed.
BUILD_DIR="build"
# Name of the main C++ source file that this script expects to find
# within the provided source directory.
MAIN_CPP_SOURCE_FILE="main.cpp"
# Name of the Python script responsible for plotting the benchmark results.
# This script is expected to be in the same directory as run_benchmark.sh.
PYTHON_PLOTTER_SCRIPT="plot.py"
# =============================================================

# Function: show_help
# Purpose: Displays a detailed usage message for the script, including options,
#          arguments, and key assumptions.
# Parameters: None
# Returns: None (prints to standard output)
show_help() {
    echo "Usage: $0 [OPTION] <source_directory>"
    echo
    echo "Options:"
    echo "  -c                   Clean generated files (logs/, build/, plots/)"
    echo "  -h                   Show this help message"
    echo
    echo "Arguments:"
    echo "  <source_directory>   The directory containing your '${MAIN_CPP_SOURCE_FILE}' file."
    echo
    echo "This script compiles the C++ benchmark, runs it, and then plots the results."
    echo "Assumptions:"
    echo "  - All necessary C++ headers (e.g., FUNCTION_BENCHMARK.HPP, utils.hpp) must be discoverable by 'g++'"
    echo "    via relative paths from your C++ source files (e.g., #include \"../utils.hpp\")."
    echo "  - Your C++ program (${MAIN_CPP_SOURCE_FILE}) generates a CSV file named 'raw_<source_directory_name>_data.csv'"
    echo "    inside 'logs/' in the current working directory."
    echo "  - The plotting script ('${PYTHON_PLOTTER_SCRIPT}') is in the same directory as this script."
}

# Function: clean_all
# Purpose: Removes all directories and files generated by the benchmarking process.
#          This includes the build directory, plots directory, and logs directory.
# Parameters: None
# Returns: None (prints cleanup status to standard output)
clean_all() {
    echo "[*] Cleaning generated files..."
    # Remove the build directory. rm -rf is idempotent.
    rm -rf "$BUILD_DIR"
    # Remove the plots directory.
    rm -rf "plots"
    # Remove the logs directory.
    rm -rf "logs"
    echo "[+] Clean complete."
}


# ===================== Main Execution Flow ======================

# Parse command line options using getopts.
# 'c' and 'h' are recognized as options.
while getopts "ch" opt; do
    case $opt in
        c)
            # If -c (clean) option is provided, call the clean_all function
            # and then exit the script.
            clean_all
            exit 0
            ;;
        h)
            # If -h (help) option is provided, display the help message
            # and then exit the script.
            show_help
            exit 0
            ;;
        \?)
            # Handle invalid options. $OPTARG holds the invalid option.
            echo "Error: Invalid option: -$OPTARG" >&2 # Output error to stderr
            show_help
            exit 1 # Exit with a non-zero status to indicate an error
            ;;
    esac
done
# Shift positional parameters so that "$1" refers to the first non-option argument.
shift $((OPTIND - 1))

# Check if a source directory argument was provided after option parsing.
if [[ $# -eq 0 ]]; then
    # If no argument is provided, show the help message and exit.
    show_help
    exit 0 # Exit with 0 as it's a usage/help request, not an execution error.
fi

# Store the provided source directory path.
SOURCE_DIRECTORY="$1"
# Construct the full path to the main C++ source file.
MAIN_CPP_PATH="${SOURCE_DIRECTORY}/${MAIN_CPP_SOURCE_FILE}"
# Construct the full path for the compiled executable.
OUTPUT_EXE_PATH="${BUILD_DIR}/main.exe"

# Dynamically set the base name for the CSV file.
# This ensures the CSV name is related to the source directory, e.g.,
# if SOURCE_DIRECTORY is 'sine_wave', CSV_BASE_NAME will be 'sine_wave'.
CSV_BASE_NAME="$(basename "$SOURCE_DIRECTORY")"
# Construct the full CSV filename based on the base name.
CSV_FILE_NAME="raw_${CSV_BASE_NAME}_data.csv"
# Define the expected full path to the generated CSV file.
CSV_FILE_PATH="results/${CSV_FILE_NAME}"

# Validate source directory existence.
# The script exits if the directory is not found, providing a descriptive error.
if [[ ! -d "$SOURCE_DIRECTORY" ]]; then
    echo "Error: Source directory '$SOURCE_DIRECTORY' not found."
    show_help
    exit 1
fi

# Validate main C++ source file existence within the source directory.
# The script exits if the file is not found.
if [[ ! -f "$MAIN_CPP_PATH" ]]; then
    echo "Error: Main C++ source file '$MAIN_CPP_PATH' not found."
    echo "Please ensure '${MAIN_CPP_SOURCE_FILE}' exists in '$SOURCE_DIRECTORY'."
    exit 1
fi

# Create the build directory if it doesn't already exist.
# mkdir -p creates parent directories as needed and does not error if it exists.
mkdir -p "$BUILD_DIR"
# Check the exit status of the previous command (mkdir -p).
if [ $? -ne 0 ]; then
    echo "Error: Failed to create build directory '$BUILD_DIR'."
    exit 1
fi

# Compile the C++ code using g++ with -O3 optimization.
# The output (including errors) from g++ will be displayed directly to the console.
g++ -O3 "$MAIN_CPP_PATH" -o "$OUTPUT_EXE_PATH"
# Check the exit status of the g++ compilation command.
if [ $? -ne 0 ]; then
    echo "Error: C++ compilation failed for '$MAIN_CPP_PATH'. Check compiler output above for details."
    # Clean up the partially created build directory upon compilation failure.
    rm -rf "$BUILD_DIR"
    exit 1
fi

# Execute the compiled C++ benchmark program.
# The output (including errors) from the C++ executable will be displayed directly.
"$OUTPUT_EXE_PATH"
# Check the exit status of the C++ benchmark execution.
if [ $? -ne 0 ]; then
    echo "Error: C++ benchmark execution failed for '$OUTPUT_EXE_PATH'. Check program output above for details."
    exit 1
fi

# Validate that the C++ program generated the expected CSV data file.
# This is crucial for the plotting step to proceed correctly.
if [[ ! -f "$CSV_FILE_PATH" ]]; then
    echo "Error: Expected CSV file '$CSV_FILE_PATH' not found after C++ execution."
    echo "Please ensure your C++ program generates the CSV file at the expected path."
    exit 1
fi

# Validate that the Python plotting script exists.
# The script exits if the plotter script is not found.
if [[ ! -f "$PYTHON_PLOTTER_SCRIPT" ]]; then
    echo "Error: Python plotting script '$PYTHON_PLOTTER_SCRIPT' not found."
    echo "Please ensure '${PYTHON_PLOTTER_SCRIPT}' is in the same directory as this script."
    exit 1
fi

# Run the Python plotting script, passing the generated CSV file as an argument.
# The output (including errors) from the Python script will be displayed directly.
python3 "$PYTHON_PLOTTER_SCRIPT" "$CSV_FILE_PATH"
# Check the exit status of the Python plotting script.
if [ $? -ne 0 ]; then
    echo "Error: Python plotting script failed for '$CSV_FILE_PATH'. Check its output for details."
    exit 1
fi

# Final success message if all steps completed without error.
echo -e "\n[SUCCESS] Benchmark and plotting process completed for '$SOURCE_DIRECTORY'."
